import ast
BASE = "/home/pi/africabox"

install = '#!/bin/bash\n# ============================================================\n# AKILI IoT Platform — Complete Installer\n# CrossTech Path 2026\n# Version: 1.0.0\n# Updated: 2026-06-01\n#\n# Usage:\n#   Fresh Pi OS install:\n#     curl -sSL https://raw.githubusercontent.com/ericfanane/akili-automation-language/main/install.sh | bash\n#\n#   Or copy this file to the Pi and run:\n#     chmod +x install.sh && ./install.sh\n#\n#   Restore from backup:\n#     ./install.sh --restore /path/to/backup.zip\n# ============================================================\n\nset -e\nRED=\'\\033[0;31m\'; GREEN=\'\\033[0;32m\'; YELLOW=\'\\033[1;33m\'; BLUE=\'\\033[0;34m\'; NC=\'\\033[0m\'\nok()   { echo -e "${GREEN}✅ $1${NC}"; }\nwarn() { echo -e "${YELLOW}⚠  $1${NC}"; }\nerr()  { echo -e "${RED}❌ $1${NC}"; exit 1; }\ninfo() { echo -e "${BLUE}ℹ  $1${NC}"; }\n\necho ""\necho "============================================================"\necho "  AKILI IoT Platform — Installer v1.0.0"\necho "  CrossTech Path 2026"\necho "============================================================"\necho ""\n\n# ── Check we are on a Raspberry Pi ──────────────────────────\nif ! grep -q "Raspberry Pi" /proc/cpuinfo 2>/dev/null; then\n    warn "Not detected as Raspberry Pi — continuing anyway"\nfi\n\n# ── Check running as pi user ────────────────────────────────\nif [ "$USER" != "pi" ]; then\n    warn "Not running as pi user (current: $USER)"\nfi\n\nBASE="/home/pi/africabox"\nBACKUP_FILE=""\n\n# ── Parse arguments ─────────────────────────────────────────\nif [ "$1" = "--restore" ] && [ -n "$2" ]; then\n    BACKUP_FILE="$2"\n    info "Restore mode: $BACKUP_FILE"\nfi\n\n# ============================================================\n# STEP 1 — System update\n# ============================================================\necho ""\ninfo "Step 1/8 — System update"\nsudo apt-get update -q\nsudo apt-get upgrade -y -q\nok "System updated"\n\n# ============================================================\n# STEP 2 — System packages\n# ============================================================\necho ""\ninfo "Step 2/8 — Installing system packages"\nsudo apt-get install -y -q \\\n    python3 python3-pip python3-venv \\\n    git zip unzip curl wget \\\n    i2c-tools python3-smbus \\\n    libatlas-base-dev \\\n    minicom screen \\\n    network-manager \\\n    sqlite3\nok "System packages installed"\n\n# ============================================================\n# STEP 3 — Python libraries\n# ============================================================\necho ""\ninfo "Step 3/8 — Installing Python libraries"\npip3 install --break-system-packages \\\n    w1thermsensor \\\n    adafruit-circuitpython-ads1x15 \\\n    gpiozero \\\n    RPi.GPIO \\\n    requests \\\n    pyserial \\\n    flask 2>/dev/null || true\n\n# Verify critical ones\npython3 -c "import w1thermsensor" 2>/dev/null && ok "w1thermsensor" || warn "w1thermsensor not installed"\npython3 -c "import adafruit_ads1x15" 2>/dev/null && ok "adafruit_ads1x15" || warn "adafruit_ads1x15 not installed"\npython3 -c "import gpiozero" 2>/dev/null && ok "gpiozero" || warn "gpiozero not installed"\npython3 -c "import serial" 2>/dev/null && ok "pyserial" || warn "pyserial not installed"\n\n# ============================================================\n# STEP 4 — Enable hardware interfaces\n# ============================================================\necho ""\ninfo "Step 4/8 — Enabling hardware interfaces"\n\n# Enable I2C\nsudo raspi-config nonint do_i2c 0 2>/dev/null || warn "Could not enable I2C via raspi-config"\n\n# Enable 1-Wire\nsudo raspi-config nonint do_onewire 0 2>/dev/null || warn "Could not enable 1-Wire via raspi-config"\n\n# Add 1-Wire overlay to config if not already there\nif ! grep -q "dtoverlay=w1-gpio" /boot/firmware/config.txt 2>/dev/null; then\n    echo "dtoverlay=w1-gpio,gpiopin=4" | sudo tee -a /boot/firmware/config.txt\n    ok "1-Wire overlay added (GPIO4)"\nelse\n    ok "1-Wire overlay already configured"\nfi\n\n# Enable serial for SIM7600E (disable console on serial)\nif ! grep -q "enable_uart=1" /boot/firmware/config.txt 2>/dev/null; then\n    echo "enable_uart=1" | sudo tee -a /boot/firmware/config.txt\nfi\nsudo raspi-config nonint do_serial_hw 0 2>/dev/null || true\nsudo raspi-config nonint do_serial_cons 1 2>/dev/null || true\nok "Hardware interfaces enabled"\n\n# ============================================================\n# STEP 5 — Create directories\n# ============================================================\necho ""\ninfo "Step 5/8 — Creating directories"\nmkdir -p $BASE\nmkdir -p $BASE/ai_proxy\nmkdir -p $BASE/static\nmkdir -p $BASE/reports\nmkdir -p /media/pi/sda\nok "Directories created"\n\n# ============================================================\n# STEP 6 — Restore from backup OR create fresh settings\n# ============================================================\necho ""\ninfo "Step 6/8 — Installing AKILI files"\n\nif [ -n "$BACKUP_FILE" ] && [ -f "$BACKUP_FILE" ]; then\n    info "Restoring from backup: $BACKUP_FILE"\n    cd /home/pi\n    unzip -o "$BACKUP_FILE" -d /home/pi/\n    ok "Backup restored"\nelse\n    warn "No backup file specified"\n    info "Please copy your africabox files to $BASE manually"\n    info "Or run: ./install.sh --restore /path/to/backup.zip"\nfi\n\n# ============================================================\n# STEP 7 — Create systemd services\n# ============================================================\necho ""\ninfo "Step 7/8 — Creating systemd services"\n\n# Main AKILI service\nsudo tee /etc/systemd/system/africabox.service > /dev/null << \'EOF\'\n[Unit]\nDescription=AKILI IoT Platform — CrossTech Path\nAfter=network.target\n\n[Service]\nType=simple\nUser=pi\nWorkingDirectory=/home/pi/africabox\nExecStart=/usr/bin/python3 /home/pi/africabox/africabox.py\nRestart=always\nRestartSec=5\nStandardOutput=journal\nStandardError=journal\n\n[Install]\nWantedBy=multi-user.target\nEOF\n\n# AI Proxy service\nsudo tee /etc/systemd/system/akili-ai.service > /dev/null << \'EOF\'\n[Unit]\nDescription=AKILI AI Proxy — CrossTech Path\nAfter=network.target africabox.service\n\n[Service]\nType=simple\nUser=pi\nWorkingDirectory=/home/pi/africabox/ai_proxy\nExecStart=/usr/bin/python3 /home/pi/africabox/ai_proxy/server.py\nRestart=always\nRestartSec=10\nStandardOutput=journal\nStandardError=journal\n\n[Install]\nWantedBy=multi-user.target\nEOF\n\nsudo systemctl daemon-reload\nsudo systemctl enable africabox\nsudo systemctl enable akili-ai\nok "Systemd services created and enabled"\n\n# ============================================================\n# STEP 8 — Start services\n# ============================================================\necho ""\ninfo "Step 8/8 — Starting AKILI"\n\nif [ -f "$BASE/africabox.py" ]; then\n    sudo systemctl start africabox\n    sleep 3\n    if sudo systemctl is-active --quiet africabox; then\n        ok "AKILI is running"\n    else\n        warn "AKILI failed to start — check: sudo journalctl -u africabox -n 20"\n    fi\n\n    sudo systemctl start akili-ai\n    sleep 2\n    if sudo systemctl is-active --quiet akili-ai; then\n        ok "AI Proxy is running"\n    else\n        warn "AI Proxy failed to start"\n    fi\nelse\n    warn "africabox.py not found — services not started"\n    info "Copy your files to $BASE then run: sudo systemctl start africabox"\nfi\n\n# ============================================================\n# SUMMARY\n# ============================================================\necho ""\necho "============================================================"\necho -e "${GREEN}  AKILI Installation Complete${NC}"\necho "============================================================"\necho ""\n\n# Get Pi IP\nIP=$(hostname -I | awk \'{print $1}\')\necho "  Platform:  http://$IP:8080"\necho "  AI Proxy:  http://$IP:9090/health"\necho ""\necho "  Useful commands:"\necho "  sudo systemctl status africabox"\necho "  sudo systemctl restart africabox"\necho "  sudo journalctl -u africabox -f"\necho ""\necho "  Hardware GPIO map:"\necho "  Relay 1 → GPIO 27    Relay 5 → GPIO 25"\necho "  Relay 2 → GPIO 22    Relay 6 → GPIO 8"\necho "  Relay 3 → GPIO 23    Relay 7 → GPIO 7"\necho "  Relay 4 → GPIO 24    Relay 8 → GPIO 16"\necho "  DS18B20 → GPIO 4 (1-Wire)"\necho "  ADS1115 → I2C (SDA=GPIO2, SCL=GPIO3)"\necho "  SIM7600E → /dev/ttyUSB2"\necho ""\necho "  ⚠  Reboot required for hardware interfaces:"\necho "  sudo reboot"\necho ""\necho "  Backup:"\necho "  sudo python3 /home/pi/africabox/backup_akili.py"\necho "============================================================"\n'
with open(BASE+"/install.sh","w") as f:
    f.write(install)
import os
os.chmod(BASE+"/install.sh", 0o755)
print("OK install.sh")

readme = '# AKILI IoT Platform — Installation Guide\n**Version:** 1.0.0 | **Updated:** 2026-06-01 | **Author:** CrossTech Path\n\n---\n\n## What You Need\n\n| Item | Spec | Cost |\n|---|---|---|\n| Raspberry Pi 4 | 2GB RAM minimum | €50 |\n| MicroSD card | 32GB Class 10 | €10 |\n| Power supply | USB-C 5V 3A | €10 |\n| 8-channel relay board | 5V trigger | €15 |\n| DS18B20 temperature sensors | Waterproof version | €5 each |\n| ADS1115 ADC board | 16-bit I2C | €5 |\n| SIM7600E 4G module | With SIM card | €40 |\n| 4.7kΩ resistor | For DS18B20 | €0.10 |\n\n---\n\n## Step 1 — Flash Raspberry Pi OS\n\n1. Download **Raspberry Pi Imager** from raspberrypi.com\n2. Flash **Raspberry Pi OS Lite 64-bit** (no desktop needed)\n3. In Imager settings (gear icon) configure:\n   - Hostname: `raspberrypi-plc`\n   - Username: `pi`\n   - Password: choose a strong password\n   - WiFi: your network name and password\n   - Enable SSH: Yes\n4. Flash the SD card, insert into Pi, power on\n5. Wait 2 minutes, then SSH in:\n```bash\nssh pi@raspberrypi-plc.local\n```\n\n---\n\n## Step 2 — Copy AKILI Files\n\nCopy your latest backup ZIP to the Pi:\n```bash\nscp akili_vX_YYYYMMDD_BACKUP.zip pi@raspberrypi-plc.local:/home/pi/\n```\n\n---\n\n## Step 3 — Run Installer\n\n```bash\nssh pi@raspberrypi-plc.local\nchmod +x install.sh\n./install.sh --restore /home/pi/akili_vX_YYYYMMDD_BACKUP.zip\n```\n\nThe installer does everything automatically:\n- Updates the system\n- Installs all Python libraries\n- Enables I2C, 1-Wire, Serial interfaces\n- Creates systemd services\n- Restores your backup\n- Starts AKILI\n\n---\n\n## Step 4 — Reboot\n\n```bash\nsudo reboot\n```\n\nAfter reboot AKILI starts automatically. Access at:\n```\nhttp://raspberrypi-plc.local:8080\n```\n\n---\n\n## Step 5 — Wire the Hardware\n\n### Relay Board (8 channels)\n```\nRelay board VCC  → Pi 5V  (Pin 2)\nRelay board GND  → Pi GND (Pin 6)\nRelay board IN1  → Pi GPIO 27 (Pin 13)\nRelay board IN2  → Pi GPIO 22 (Pin 15)\nRelay board IN3  → Pi GPIO 23 (Pin 16)\nRelay board IN4  → Pi GPIO 24 (Pin 18)\nRelay board IN5  → Pi GPIO 25 (Pin 22)\nRelay board IN6  → Pi GPIO 8  (Pin 24)\nRelay board IN7  → Pi GPIO 7  (Pin 26)\nRelay board IN8  → Pi GPIO 16 (Pin 36)\n```\n\n### DS18B20 Temperature Sensor (1-Wire)\n```\nDS18B20 RED    → Pi 3.3V (Pin 1)\nDS18B20 BLACK  → Pi GND  (Pin 9)\nDS18B20 YELLOW → Pi GPIO 4 (Pin 7)\n4.7kΩ resistor between RED and YELLOW\n```\nMultiple DS18B20 sensors can share the same 3 wires (bus).\n\n### ADS1115 Analog ADC (I2C)\n```\nADS1115 VDD  → Pi 3.3V (Pin 1)\nADS1115 GND  → Pi GND  (Pin 6)\nADS1115 SDA  → Pi GPIO 2 / SDA (Pin 3)\nADS1115 SCL  → Pi GPIO 3 / SCL (Pin 5)\nADS1115 ADDR → Pi GND  (address 0x48)\n```\nAnalog channels A0-A3 connect to your sensors (pH probe, soil moisture, 4-20mA via 250Ω resistor).\n\n### SIM7600E 4G Module (Serial)\n```\nSIM7600E TX  → Pi GPIO 15 / RXD (Pin 10)\nSIM7600E RX  → Pi GPIO 14 / TXD (Pin 8)\nSIM7600E GND → Pi GND (Pin 6)\nSIM7600E VCC → External 5V supply (needs 2A)\n```\nInsert SIM card with SMS capability. Port: `/dev/ttyUSB2`\n\n---\n\n## Step 6 — Configure AKILI\n\n1. Open `http://raspberrypi-plc.local:8080`\n2. Run the setup wizard (5 steps)\n3. Go to **Settings** and enter:\n   - Installation name and location\n   - Anthropic API key (from console.anthropic.com)\n   - Alert phone number (for SMS)\n   - Email settings (for email alerts)\n4. Go to **System** page and verify hardware is detected\n\n---\n\n## Step 7 — Test Hardware\n\nRun the hardware test:\n```bash\npython3 /home/pi/africabox/test_hardware.py\n```\n\nThis verifies:\n- All relay channels switch correctly\n- DS18B20 sensors are reading\n- ADS1115 channels are responding\n- SIM7600E can send a test SMS\n\n---\n\n## Useful Commands\n\n```bash\n# Check status\nsudo systemctl status africabox\nsudo systemctl status akili-ai\n\n# Restart\nsudo systemctl restart africabox\nsudo systemctl restart akili-ai\n\n# View logs\nsudo journalctl -u africabox -f\nsudo journalctl -u africabox -n 50\n\n# Backup\nsudo mount /dev/sda /media/pi/sda\nsudo python3 /home/pi/africabox/backup_akili.py\n\n# Run tests\npython3 /home/pi/africabox/test_severe.py\n\n# Check database\nsqlite3 /home/pi/africabox/africabox.db ".tables"\n```\n\n---\n\n## Troubleshooting\n\n**AKILI not starting:**\n```bash\nsudo journalctl -u africabox -n 30 --no-pager\n```\n\n**No temperature sensors detected:**\n```bash\nls /sys/bus/w1/devices/\n# Should show 28-xxxxxxxxxxxx entries\n# If empty: check wiring and 4.7kΩ resistor\n```\n\n**I2C not working:**\n```bash\nsudo i2cdetect -y 1\n# Should show 0x48 for ADS1115\n# If empty: check SDA/SCL wiring\n```\n\n**SMS not sending:**\n```bash\npython3 -c "\nimport serial, time\ns = serial.Serial(\'/dev/ttyUSB2\', 115200, timeout=1)\ns.write(b\'AT\\r\\n\')\ntime.sleep(0.5)\nprint(s.read(100))\n"\n# Should return b\'AT\\r\\n\\r\\nOK\\r\\n\'\n```\n\n**Relay not switching:**\n```bash\npython3 -c "\nfrom gpiozero import OutputDevice\nr = OutputDevice(27, active_high=False)\nr.on(); import time; time.sleep(2); r.off()\nprint(\'Relay 1 test OK\')\n"\n```\n\n---\n\n## GPIO Pin Reference\n\n```\nPin 1  → 3.3V          Pin 2  → 5V\nPin 3  → SDA (I2C)     Pin 4  → 5V\nPin 5  → SCL (I2C)     Pin 6  → GND\nPin 7  → GPIO 4 (1W)   Pin 8  → TXD\nPin 9  → GND           Pin 10 → RXD\nPin 13 → GPIO 27 R1    Pin 15 → GPIO 22 R2\nPin 16 → GPIO 23 R3    Pin 18 → GPIO 24 R4\nPin 22 → GPIO 25 R5    Pin 24 → GPIO 8  R6\nPin 26 → GPIO 7  R7    Pin 36 → GPIO 16 R8\n```\n\n---\n\n## File Structure\n\n```\n/home/pi/africabox/\n├── africabox.py          Main server (3300+ lines)\n├── pid_control.py        PID control engine\n├── rule_engine.py        Automation rule engine\n├── sequence_engine.py    Sequence (SFC) engine\n├── interlock_engine.py   Safety interlock engine\n├── hardware.py           Hardware drivers\n├── auto_advisor.py       AI Advisor\n├── ai_tuner.py           AI Auto-Tuner\n├── anomaly_explainer.py  Anomaly explainability\n├── predictive_failure.py Predictive failure detection\n├── scheduler.py          Background task scheduler\n├── email_alerts.py       Email/SMS/WhatsApp alerts\n├── report_generator.py   HACCP/WHO report generator\n├── modules.py            Industry module definitions\n├── auth.py               Authentication\n├── settings.json         Configuration file\n├── africabox.db          SQLite database\n├── backup_akili.py       Backup script\n├── test_severe.py        Test suite (87 tests)\n├── ai_proxy/\n│   └── server.py         Claude AI proxy\n├── static/\n│   ├── akili_nav.js      Navigation component\n│   └── akili_ai.js       AI chat widget\n└── *.html                Page templates\n```\n\n---\n\n## Version History\n\n| Version | Date | Changes |\n|---|---|---|\n| 1.0.0 | 2026-06-01 | Initial release — Phase 2 First Light |\n\n---\n\n*CrossTech Path | akilijuma.org | eric.fanane@hotmail.com*\n'
with open(BASE+"/README_INSTALL.md","w") as f:
    f.write(readme)
print("OK README_INSTALL.md")
